 local decayFields=C:CreateRow(decay.content,{gap=8,padding=2});decayFields:Add(labeled(decayFields.frame,L["ACTIVITY_POINTS_DECAY_MODE"],mode),{weight=1,minWidth=150});decayFields:Add(labeled(decayFields.frame,L["ACTIVITY_POINTS_DECAY_INTERVAL"],interval),{weight=1,minWidth=140});decayFields:Add(labeled(decayFields.frame,L["ACTIVITY_POINTS_DECAY_AMOUNT"],amount),{weight=1,minWidth=140});decay:Add(decayFields,{height=66});local saveDecay=C:CreateButton(decay.content,{text=L["ACTIVITY_POINTS_SAVE_DECAY"],width=150,onClick=function()local data=guildData();self:SetDecay(self.adminDecayValue or(data and data.decay.mode)or"NONE",tonumber(interval.edit:GetText()),tonumber(amount.edit:GetText()));self:RefreshAdmin()end});decay:Add(saveDecay,{height=30});column:Add(decay,{height=125})
