function Points:RefreshAdmin()
 if not self.adminTable then return end;self.adminTable:SetData(self:ListRules());if self.adminEnableButton then self.adminEnableButton:SetEnabled(self.adminSelectedRule~=nil)end;local data=guildData();if data then local mode=data.decay.mode or"NONE";self.adminDecayMode:SetValue(mode,L["ACTIVITY_POINTS_DECAY_"..mode]or mode);self.adminDecayInterval.edit:SetText(tostring(data.decay.intervalDays or 30));self.adminDecayAmount.edit:SetText(tostring(data.decay.amount or 0));self.adminDecayValue=mode end
